package io.github.artemiscore.artemisappsec.organization.service;

import java.time.Instant;
import java.util.UUID;

/**
 * {@code managed} keys were generated by Artemis and can clone the repository; others only have a public part.
 * {@code publicKey} is set for managed keys (to add it to the Git provider).
 */
public record DeployKeyView(UUID id, String name, String keyType, String fingerprint, String repository,
		Instant addedAt, Instant lastUsedAt, boolean managed, String publicKey) {
}
